package com.oms.order.service;

import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;

/** Platform facts survive failed conversion. No platform writes, stock commands or new sales orders. */
@Service public class PlatformExchangeService {
    @Resource OrderRepository repository;
    @Resource ExchangeService exchanges;
    public PlatformExchangeService() {}
    PlatformExchangeService(OrderRepository r,ExchangeService e){repository=r;exchanges=e;}
    TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    Map<String,Object> row(String company,long id,boolean lock){List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_platform_exchange WHERE company_code=? AND id=?"+(lock?" FOR UPDATE":""),ROW,company,id);require(rows.size()==1,"平台换货不存在或无权访问");return rows.get(0);}
    private void lockShop(String company,long channel){require(!repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,channel).isEmpty(),"请先配置店铺换货接入");}
    private String shortText(Object value,int max){String s=value==null?"":String.valueOf(value);return s.substring(0,Math.min(max,s.length()));}
    private List<Map<String,Object>> differences(Map<String,Object> old,Map<String,Object> fresh){List<Map<String,Object>> out=new ArrayList<>();for(String key:Arrays.asList("biz_order_id","num","bought_sku","exchange_sku","status","refund_phase","speed_exchange","time_out","buyer_address","buyer_name","buyer_phone","oaid","buyer_logistic_no","seller_logistic_no"))if(!text(old,key).equals(text(fresh,key)))out.add(map("field",key,"before",key.startsWith("buyer_")&&!key.equals("buyer_logistic_no")||key.equals("oaid")?"已隐藏":shortText(old.get(key),1000),"after",key.startsWith("buyer_")&&!key.equals("buyer_logistic_no")||key.equals("oaid")?"已变更":shortText(fresh.get(key),1000)));return out;}
    public Map<String,Object> ingest(String company,long channel,Map<String,Object> input,String actor){
        Map<String,Object> payload=new LinkedHashMap<>(input);if(text(payload,"biz_order_id").isEmpty()&&!text(payload,"bizorder_id").isEmpty())payload.put("biz_order_id",payload.get("bizorder_id"));
        String dispute=text(payload,"dispute_id");require(dispute.matches("[1-9][0-9]{0,63}"),"平台申请缺少可靠换货单号");String encoded=ExchangeService.canonical(payload),digest=hash(encoded);require(encoded.length()<=2097152,"平台换货报文超过2MB，请核对来源");String error="";
        try{require(text(payload,"biz_order_id").matches("[1-9][0-9]{0,63}"),"平台申请缺少可靠子单号");time(text(payload,"modified"));require(number(payload,"num")>0&&number(payload,"num")<=100000000,"平台申请数量无效");require(text(payload,"bought_sku").length()<=1000&&text(payload,"exchange_sku").length()<=1000,"平台规格内容过长");require(!text(payload,"status").isEmpty()&&text(payload,"status").length()<=64,"平台状态无效");}catch(IllegalArgumentException invalid){error=invalid instanceof NumberFormatException?"平台数量格式无效":shortText(invalid.getMessage(),500);}
        final String invalid=error;
        return tx().execute(s->{lockShop(company,channel);List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_platform_exchange WHERE company_code=? AND channel_id=? AND dispute_id=? FOR UPDATE",ROW,company,channel,dispute);Map<String,Object> before=rows.isEmpty()?null:rows.get(0);String outcome=invalid.isEmpty()?"NEW":"INVALID";
            if(before!=null&&invalid.isEmpty()){int cmp=before.get("source_modified")==null?1:time(text(payload,"modified")).compareTo(time(text(before,"source_modified")));outcome=cmp<0?"OLDER":digest.equals(text(before,"payload_hash"))?"DUPLICATE":cmp==0?"CONFLICT":"UPDATED";if(!text(before,"platform_oid").isEmpty()&&!text(before,"platform_oid").equals(text(payload,"biz_order_id")))outcome="CONFLICT";if("DUPLICATE".equals(outcome)&&"INVALID".equals(text(before,"source_state")))outcome="UPDATED";}
            long id;if(before==null){id=repository.insert("INSERT INTO oms_platform_exchange(company_code,channel_id,dispute_id,platform_oid,payload,payload_hash,source_state,source_error) VALUES (?,?,?,?,?,?,?,?)",company,channel,dispute,text(payload,"biz_order_id").matches("[1-9][0-9]{0,63}")?text(payload,"biz_order_id"):"",encoded,digest,invalid.isEmpty()?"VALID":"INVALID",invalid);before=row(company,id,true);}else id=number(before,"id");
            if(before.get("business_exchange_id")==null){List<Map<String,Object>> linked=repository.db().query("SELECT id FROM oms_exchange WHERE company_code=? AND channel_id=? AND dispute_id=? AND source_kind='PLATFORM'",ROW,company,channel,dispute);if(linked.size()==1){repository.db().update("UPDATE oms_platform_exchange SET business_exchange_id=?,conversion_state='SUCCESS' WHERE company_code=? AND id=?",linked.get(0).get("id"),company,id);repository.db().update("UPDATE oms_exchange SET platform_exchange_id=? WHERE company_code=? AND id=?",id,company,linked.get(0).get("id"));before=row(company,id,false);}}
            List<Map<String,Object>> diff=differences(before.get("source_modified")==null?Collections.emptyMap():ExchangeService.object(before.get("payload")),payload);Object modified=invalid.isEmpty()?payload.get("modified"):null;
            repository.db().update("INSERT IGNORE INTO oms_platform_exchange_snapshot(company_code,platform_exchange_id,source_modified,payload_hash,payload,outcome,difference_json,actor) VALUES (?,?,?,?,?,?,?,?)",company,id,modified,digest,encoded,outcome,encode(diff),actor);
            if(Arrays.asList("NEW","UPDATED").contains(outcome)){Object deadline=null;try{if(!text(payload,"time_out").isEmpty())deadline=time(text(payload,"time_out")).format(TIME);}catch(IllegalArgumentException ignored){}
                repository.db().update("UPDATE oms_platform_exchange SET platform_oid=?,platform_status=?,source_phase=?,speed_exchange=?,requested_quantity=?,original_description=?,target_description=?,source_modified=?,platform_deadline=?,payload=?,payload_hash=?,source_state='VALID',source_error='',version=version+?,last_sync=NOW(),conversion_state=IF(business_exchange_id IS NULL,'WAITING',conversion_state),conversion_error=IF(business_exchange_id IS NULL,'',conversion_error),next_convert=NOW() WHERE company_code=? AND id=?",text(payload,"biz_order_id"),ExchangeService.status(text(payload,"status")),ExchangeService.phase(text(payload,"refund_phase")),ExchangeService.speed(payload),number(payload,"num"),text(payload,"bought_sku"),text(payload,"exchange_sku"),modified,deadline,encoded,digest,"UPDATED".equals(outcome)?1:0,company,id);
                if(before.get("business_exchange_id")!=null)project(company,row(company,id,false),payload,diff,actor);
            }else if(Arrays.asList("INVALID","CONFLICT").contains(outcome)){String why="CONFLICT".equals(outcome)?"平台子单身份或同版本内容冲突，保留原资料与业务关联":invalid;repository.db().update("UPDATE oms_platform_exchange SET source_state=?,source_error=?,last_sync=NOW() WHERE company_code=? AND id=?",outcome,why,company,id);if(before.get("business_exchange_id")!=null)repository.db().update("UPDATE oms_exchange SET state='BLOCKED',problem_codes='SOURCE_CONFLICT',problem_message=?,control_version=control_version+1,next_attempt=NULL WHERE company_code=? AND id=?",why,company,before.get("business_exchange_id"));}
            else repository.db().update("UPDATE oms_platform_exchange SET last_sync=NOW() WHERE company_code=? AND id=?",company,id);
            associate(company,id);Map<String,Object> current=row(company,id,false);if(current.get("business_exchange_id")==null&&"VALID".equals(text(current,"source_state"))&&Arrays.asList("4","14","5").contains(text(current,"platform_status")))repository.db().update("UPDATE oms_platform_exchange SET conversion_state='SKIPPED',conversion_error='平台申请已结束，无新增执行任务；转退款请另行核对平台退款' WHERE company_code=? AND id=?",company,id);
            PlatformExchangeGuard.refresh(repository,company,channel,text(current,"platform_oid"));return map("id",id,"business_exchange_id",current.get("business_exchange_id"),"outcome",outcome);
        });
    }
    private void project(String company,Map<String,Object> source,Map<String,Object> payload,List<Map<String,Object>> diff,String actor){Map<String,Object> business=exchanges.row(company,number(source,"business_exchange_id"),true);
        if("PLATFORM".equals(text(business,"source_kind"))){if(text(business,"problem_codes").equals("SOURCE_CONFLICT")&&time(text(payload,"modified")).isAfter(time(text(business,"source_modified"))))repository.db().update("UPDATE oms_exchange SET problem_codes='',state=IF(approved_version IS NULL,'NEEDS_REVIEW',state) WHERE company_code=? AND id=?",company,business.get("id"));Map<String,Object> projected=exchanges.ingest(company,number(source,"channel_id"),payload,actor);require(number(projected,"id")==number(business,"id"),"平台换货关联不一致");}
        else {boolean changed=Arrays.asList("4","14").contains(text(source,"platform_status"))||diff.stream().anyMatch(d->Arrays.asList("biz_order_id","num","exchange_sku","bought_sku","speed_exchange","buyer_address","buyer_name","buyer_phone","oaid").contains(text(d,"field")));if(changed)repository.db().update("UPDATE oms_exchange SET state='BLOCKED',problem_codes='LINKED_PLATFORM_REVIEW',problem_message='关联平台申请变化或关闭，请核对原协商执行事实',control_version=control_version+1,next_attempt=NULL WHERE company_code=? AND id=?",company,business.get("id"));exchanges.event(company,number(business,"id"),"PLATFORM_UPDATE",text(business,"state"),number(business,"control_version"),"关联平台资料已更新；协商单不重复履约",null,actor);}
    }
    private List<Map<String,Object>> originals(String company,Map<String,Object> p){return repository.db().query("SELECT o.id order_id,o.order_sn,o.platform_tid,o.platform_order_id,l.id line_id FROM oms_order o JOIN oms_order_line l ON l.company_code=o.company_code AND l.order_id=o.id WHERE o.company_code=? AND o.channel_id=? AND l.platform_oid=? AND o.business_type='SALE' AND l.exchange_id IS NULL ORDER BY o.id,l.id LIMIT 2",ROW,company,p.get("channel_id"),p.get("platform_oid"));}
    private void associate(String company,long id){Map<String,Object> p=row(company,id,false);List<Map<String,Object>> originals=originals(company,p);if(originals.size()==1)repository.db().update("UPDATE oms_platform_exchange SET order_id=?,platform_tid=? WHERE company_code=? AND id=?",originals.get(0).get("order_id"),originals.get(0).get("platform_tid"),company,id);}
    public Map<String,Object> convert(String company,long id,String actor){Map<String,Object> hint=row(company,id,false);return tx().execute(s->{lockShop(company,number(hint,"channel_id"));Map<String,Object> p=row(company,id,true);if(p.get("business_exchange_id")!=null)return map("state","SUCCESS","id",p.get("business_exchange_id"));associate(company,id);p=row(company,id,false);String error="";
        if(!"VALID".equals(text(p,"source_state")))error="来源资料有异常，请先核对平台申请";else if(Arrays.asList("4","14","5").contains(text(p,"platform_status"))){repository.db().update("UPDATE oms_platform_exchange SET conversion_state='SKIPPED',conversion_error='平台申请已结束，无需创建执行任务' WHERE company_code=? AND id=?",company,id);return map("state","SKIPPED");}else if(originals(company,p).size()!=1)error="未找到唯一原业务订单和子单，请先同步原订单后重试关联";
        else if(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange WHERE company_code=? AND channel_id=? AND order_id=? AND platform_oid=? AND source_kind='INTERNAL' AND state NOT IN ('CANCELED','REJECTED','CLOSED')",Long.class,company,p.get("channel_id"),p.get("order_id"),p.get("platform_oid"))>0)error="存在同子单协商换货，请先核对并关联已有业务单，避免重复履约";
        if(!error.isEmpty()){repository.db().update("UPDATE oms_platform_exchange SET conversion_state='FAILED',conversion_error=?,next_convert=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",error,company,id);PlatformExchangeGuard.refresh(repository,company,number(p,"channel_id"),text(p,"platform_oid"));return map("state","FAILED","message",error);}
        Map<String,Object> result=exchanges.ingest(company,number(p,"channel_id"),ExchangeService.object(p.get("payload")),actor);long b=number(result,"id");repository.db().update("UPDATE oms_exchange SET platform_exchange_id=? WHERE company_code=? AND id=?",id,company,b);repository.db().update("UPDATE oms_platform_exchange SET business_exchange_id=?,conversion_state='SUCCESS',conversion_error='' WHERE company_code=? AND id=?",b,company,id);exchanges.event(company,b,"CONVERT","NEEDS_REVIEW",number(exchanges.row(company,b,false),"control_version"),"平台换货 "+text(p,"dispute_id")+" 已转业务单；等待审核，不代表平台同意或改变库存",null,actor);PlatformExchangeGuard.refresh(repository,company,number(p,"channel_id"),text(p,"platform_oid"));return map("state","SUCCESS","id",b);
    });}
    public List<Map<String,Object>> candidates(String company,long id){Map<String,Object> p=row(company,id,false);return repository.db().query("SELECT id,exchange_sn,requested_quantity,target_sku,target_description,state,fulfillment_mode FROM oms_exchange WHERE company_code=? AND channel_id=? AND order_id=? AND platform_oid=? AND requested_quantity=? AND source_kind='INTERNAL' AND platform_exchange_id IS NULL AND state NOT IN ('CANCELED','REJECTED','CLOSED') ORDER BY id DESC LIMIT 50",ROW,company,p.get("channel_id"),p.get("order_id"),p.get("platform_oid"),p.get("requested_quantity"));}
    public Map<String,Object> link(String company,long id,Map<String,Object> input,String actor){Map<String,Object> hint=row(company,id,false);return tx().execute(s->{lockShop(company,number(hint,"channel_id"));Map<String,Object> p=row(company,id,true);require(p.get("business_exchange_id")==null&&number(p,"version")==number(input,"version")&&"VALID".equals(text(p,"source_state")),"来源已变化或已有业务关联，请刷新");require(!Arrays.asList("4","14","5").contains(text(p,"platform_status")),"平台申请已结束，请核对原事实");associate(company,id);p=row(company,id,false);require(p.get("order_id")!=null,"请先匹配唯一原订单");Map<String,Object> b=exchanges.row(company,number(input,"exchange_id"),true);String reason=text(input,"reason").trim();require(Boolean.TRUE.equals(input.get("confirmed"))&&!reason.isEmpty()&&reason.length()<=500,"请确认本次规格、数量及履约方案一致并填写依据");require("INTERNAL".equals(text(b,"source_kind"))&&number(b,"channel_id")==number(p,"channel_id")&&number(b,"order_id")==number(p,"order_id")&&text(b,"platform_oid").equals(text(p,"platform_oid"))&&number(b,"requested_quantity")==number(p,"requested_quantity"),"协商单与平台申请的原订单、子单或数量不一致");require(b.get("platform_exchange_id")==null&&!Arrays.asList("CANCELED","CLOSED","REJECTED").contains(text(b,"state")),"协商单已关联或已取消");require(b.get("lease_until")==null||time(text(b,"lease_until")).isBefore(java.time.LocalDateTime.now()),"协商单正在执行，请稍后核对");repository.db().update("UPDATE oms_exchange SET platform_exchange_id=?,control_version=control_version+1 WHERE company_code=? AND id=?",id,company,b.get("id"));repository.db().update("UPDATE oms_platform_exchange SET business_exchange_id=?,conversion_state='SUCCESS',conversion_error='' WHERE company_code=? AND id=?",b.get("id"),company,id);exchanges.event(company,number(b,"id"),"LINK_PLATFORM",text(b,"state"),number(b,"control_version")+1,"关联平台换货 "+text(p,"dispute_id")+"；复用原履约，平台流程需单独核对："+reason,null,actor);PlatformExchangeGuard.refresh(repository,company,number(p,"channel_id"),text(p,"platform_oid"));return map("id",b.get("id"),"state","SUCCESS");});}
    void autoConvert(String company){for(Long id:repository.db().queryForList("SELECT p.id FROM oms_platform_exchange p JOIN oms_exchange_config c ON c.company_code=p.company_code AND c.channel_id=p.channel_id WHERE p.company_code=? AND c.auto_convert=1 AND p.business_exchange_id IS NULL AND p.source_state='VALID' AND p.conversion_state IN ('WAITING','FAILED') AND p.next_convert<=NOW() ORDER BY p.next_convert,p.id LIMIT 20",Long.class,company))convert(company,id,"自动转单");}
    public Map<String,Object> refresh(String company,long id,String actor){Map<String,Object> p=row(company,id,false);Map<String,Object> result=exchanges.call(company,number(p,"channel_id"),"DETAIL",map("dispute_id",p.get("dispute_id"),"fields",ExchangeService.FIELDS));ingest(company,number(p,"channel_id"),ExchangeService.object(result.get("exchange")),actor);return detail(company,id);}
    static final String FIELDS="p.id,p.channel_id,p.dispute_id,p.platform_tid,p.platform_oid,p.platform_status,p.source_phase,p.speed_exchange,p.requested_quantity,p.original_description,p.target_description,p.source_modified,p.platform_deadline,p.source_state,p.source_error,p.version,p.conversion_state,p.conversion_error,p.order_id,p.business_exchange_id,p.last_sync,p.create_time,b.exchange_sn,b.state business_state,b.target_sku,b.approved_version,b.reviewed_at,b.source_kind business_kind,o.order_sn";
    static final String JOINS=" LEFT JOIN oms_exchange b ON b.company_code=p.company_code AND b.id=p.business_exchange_id LEFT JOIN oms_order o ON o.company_code=p.company_code AND o.id=p.order_id";
    public Map<String,Object> list(String company,Map<String,String> query){String where=" WHERE p.company_code=?";List<Object> args=new ArrayList<>(Collections.singleton(company));String n=query.getOrDefault("number","").trim();require(n.length()<=128,"单号过长");if(!n.isEmpty()){where+=" AND (p.dispute_id=? OR p.platform_tid=? OR p.platform_oid=? OR b.exchange_sn=? OR o.order_sn=?)";for(int i=0;i<5;i++)args.add(n);}String channel=query.getOrDefault("channelId","");if(!channel.isEmpty()){require(channel.matches("[1-9][0-9]{0,18}"),"店铺无效");where+=" AND p.channel_id=?";args.add(Long.parseLong(channel));}
        for(String[] f:new String[][]{{"state","conversion_state"},{"platformStatus","platform_status"},{"phase","source_phase"},{"sourceState","source_state"},{"speed","speed_exchange"}}){String value=query.getOrDefault(f[0],"");require(value.length()<=64,"筛选条件过长");if(!value.isEmpty()){where+=" AND p."+f[1]+"=?";args.add(value);}}
        for(String[] f:new String[][]{{"from",">="},{"to","<="}}){String value=query.getOrDefault(f[0],"");if(!value.isEmpty()){time(value);where+=" AND p.source_modified"+f[1]+"?";args.add(value);}}
        where=PlatformDocumentQuery.append(where,args,query,false);
        long total=repository.db().queryForObject("SELECT COUNT(*) FROM oms_platform_exchange p"+JOINS+where,Long.class,args.toArray());int page=1,limit=20;try{page=Integer.parseInt(query.getOrDefault("pageNum","1"));limit=Math.min(50,size(Integer.parseInt(query.getOrDefault("pageSize","20"))));}catch(Exception bad){throw new IllegalArgumentException("分页无效");}require(page>=1&&page<=1000,"请缩小筛选范围");args.add(limit);args.add(offset(page,limit));return map("rows",repository.db().query("SELECT "+FIELDS+" FROM oms_platform_exchange p"+JOINS+where+" ORDER BY p.id DESC LIMIT ? OFFSET ?",ROW,args.toArray()),"total",total);
    }
    public Map<String,Object> detail(String company,long id){Map<String,Object> p=row(company,id,false);Map<String,Object> d=repository.db().query("SELECT "+FIELDS+" FROM oms_platform_exchange p"+JOINS+" WHERE p.company_code=? AND p.id=?",ROW,company,id).get(0);Map<String,Object> payload=ExchangeService.object(p.get("payload"));d.put("logistics",map("buyer_no",payload.get("buyer_logistic_no"),"buyer_carrier",payload.get("buyer_logistic_name"),"seller_no",payload.get("seller_logistic_no"),"seller_carrier",payload.get("seller_logistic_name")));d.put("snapshots",repository.db().query("SELECT id,source_modified,outcome,difference_json,actor,create_time FROM oms_platform_exchange_snapshot WHERE company_code=? AND platform_exchange_id=? ORDER BY id DESC LIMIT 30",ROW,company,id));d.put("tasks",repository.db().query("SELECT i.task_id,i.result,i.message,t.state,t.create_time FROM oms_exchange_sync_item i JOIN oms_exchange_sync t ON t.company_code=i.company_code AND t.id=i.task_id WHERE i.company_code=? AND i.platform_exchange_id=? ORDER BY i.id DESC LIMIT 20",ROW,company,id));
        if(p.get("business_exchange_id")!=null){Map<String,Object> b=exchanges.row(company,number(p,"business_exchange_id"),false);Map<String,Object> approved=b.get("approved_snapshot")==null?Collections.emptyMap():ExchangeService.object(b.get("approved_snapshot"));d.put("adopted",map("quantity",approved.get("quantity"),"target_sku",approved.get("target_sku"),"target_description",approved.get("target_description"),"source_modified",approved.get("source_modified"),"review_by",b.get("review_by"),"reviewed_at",b.get("reviewed_at"),"same_source",text(approved,"source_hash").equals(text(p,"payload_hash"))));}return d;}
    public Map<String,Object> snapshot(String company,long id,long snapshot){row(company,id,false);List<Map<String,Object>> rows=repository.db().query("SELECT payload,outcome,source_modified,create_time FROM oms_platform_exchange_snapshot WHERE company_code=? AND platform_exchange_id=? AND id=?",ROW,company,id,snapshot);require(rows.size()==1,"来源版本不存在或不属于当前申请");return rows.get(0);}
}
